// Deduplicación mejorada con limpieza automática
const messageId = $input.first().json.messageId;
const staticData = $getWorkflowStaticData('global');
const now = Date.now();

if (!staticData.processedIds) staticData.processedIds = {};

// Limpiar IDs antiguos (más de 1 hora)
for (const id in staticData.processedIds) {
  if (now - staticData.processedIds[id] > 3600000) {
    delete staticData.processedIds[id];
  }
}

if (staticData.processedIds[messageId]) return [];

staticData.processedIds[messageId] = now;

return [{ json: $input.first().json }];

// Buffer Manager - agrupa mensajes rápidos (ventana de 5 segundos)
const input = $input.first().json;
const phoneNumber = input.phoneNumber;
const textContent = input.textContent;
const isFromAudio = input.isFromAudio || false;
const currentTime = Date.now();

const staticData = $getWorkflowStaticData('global');
if (!staticData.messageBuffers) staticData.messageBuffers = {};

const bufferKey = 'buffer_' + phoneNumber;
const existingBuffer = staticData.messageBuffers[bufferKey];

// Si hay un buffer activo y el mensaje llega dentro de 5 segundos
if (existingBuffer && (currentTime - existingBuffer.timestamp) < 5000) {
  existingBuffer.messages.push(textContent);
  existingBuffer.timestamp = currentTime;
  // Mantener el flag de audio si alguno fue audio
  if (isFromAudio) existingBuffer.isFromAudio = true;
  return { json: { action: 'wait', phoneNumber } };
}

// Crear nuevo buffer
staticData.messageBuffers[bufferKey] = {
  messages: [textContent],
  timestamp: currentTime,
  phoneNumber: phoneNumber,
  contactName: input.contactName,
  phoneNumberId: input.phoneNumberId,
  isFromAudio: isFromAudio
};

return { json: { action: 'process', bufferKey, ...input } };

// Combinar todos los mensajes del buffer
const bufferKey = $json.bufferKey;
const staticData = $getWorkflowStaticData('global');
const buffer = staticData.messageBuffers[bufferKey];

if (!buffer) {
  return { json: { error: 'Buffer not found', phoneNumber: $json.phoneNumber } };
}

// Combinar mensajes
const combinedMessage = buffer.messages.join(' ');
const messageCount = buffer.messages.length;
const isFromAudio = buffer.isFromAudio || false;

// Limpiar buffer
delete staticData.messageBuffers[bufferKey];

return {
  json: {
    phoneNumber: buffer.phoneNumber,
    phoneNumberId: buffer.phoneNumberId,
    contactName: buffer.contactName,
    textContent: combinedMessage,
    messageCount: messageCount,
    isFromAudio: isFromAudio
  }
};

// Construir lista de servicios para WhatsApp List
const rows = $input.all().map(i => i.json).filter(r => r.id && r.nombre && r.duracion_min);
const maxRows = 10;

// Obtener datos del contexto para el mensaje personalizado
const validationData = $('Validate Service Selection')?.first()?.json;
const needsServiceFirst = validationData?.needsServiceFirst || false;
const errorType = validationData?.error || '';

let headerText = '🛍️ Servicios';
let bodyText = 'Selecciona el servicio/atención que deseas agendar:';

if (needsServiceFirst) {
  if (errorType === 'SERVICE_EXPIRED') {
    bodyText = '⏰ Tu selección anterior expiró.\n\nPor favor selecciona nuevamente el servicio que deseas:';
  } else {
    bodyText = '👋 Primero necesitas seleccionar un servicio.\n\nElige el servicio que deseas agendar:';
  }
}

const listRows = rows.slice(0, maxRows).map(r => ({
  id: `svc_${r.id}`,
  title: String(r.nombre).slice(0, 24),
  description: `${r.duracion_min} min - ${r.precio || 'Consultar'}`.slice(0, 72),
}));

return [{ json: { services: rows, listRows, headerText, bodyText, needsServiceFirst } }];

// Guardar servicio seleccionado (duración) en staticData por teléfono
const payload = $('Combine Messages').first().json;
const selectedId = String(payload.textContent || '').replace('svc_', '');
const services = $input.all().map(i => i.json);
const svc = services.find(s => String(s.id) === String(selectedId));

if (!svc) {
  // Servicio no encontrado - enviar mensaje de error
  return [{ json: { ...payload, error: 'SERVICE_NOT_FOUND', errorMessage: 'Lo siento, no encontré ese servicio. Por favor selecciona uno de la lista.' } }];
}

const staticData = $getWorkflowStaticData('global');
if (!staticData.selectedServiceByPhone) staticData.selectedServiceByPhone = {};
staticData.selectedServiceByPhone[payload.phoneNumber] = { 
  id: String(svc.id), 
  nombre: svc.nombre, 
  duracion_min: Number(svc.duracion_min || 30),
  precio: svc.precio || '',
  selectedAt: Date.now()
};

return [{ json: { ...payload, selectedService: staticData.selectedServiceByPhone[payload.phoneNumber] } }];

// Generar próximos 3 días hábiles con validación de servicio
const { phoneNumber, phoneNumberId, contactName, selectedService, error } = $json;

// Si hubo error en selección de servicio, retornar para manejar
if (error) {
  return [{ json: { phoneNumber, phoneNumberId, error, errorMessage: $json.errorMessage } }];
}

const diasHabiles = [1,2,3,4,5]; // Lun-Vie
const availableDays = [];
let date = new Date();
date.setDate(date.getDate() + 1); // Empezar desde mañana

while (availableDays.length < 3) {
  if (diasHabiles.includes(date.getDay())) {
    const dateStr = date.toISOString().split('T')[0];
    const dayNames = ['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'];
    const display = `${dayNames[date.getDay()]} ${date.getDate()}/${date.getMonth()+1}`;
    availableDays.push({ date: dateStr, display, btnId: `day_${dateStr}` });
  }
  date.setDate(date.getDate()+1);
}

return [{ json: { phoneNumber, phoneNumberId, contactName, availableDays, selectedService } }];

