// Confirmar hora elegida (usa duración del servicio guardada)
const payload = $('Combine Messages').first().json;
const { phoneNumber, phoneNumberId, contactName } = payload;
const buttonId = String(payload.textContent || '');
const parts = buttonId.replace('time_', '').split('_');
const selectedDay = parts[0];
const startHHMM = parts[1].slice(0,2) + ':' + parts[1].slice(2);

const staticData = $getWorkflowStaticData('global');
const selectedService = staticData.selectedServiceByPhone?.[phoneNumber];

if (!selectedService) {
  return [{ json: { phoneNumber, phoneNumberId, error: 'NO_SERVICE', errorMessage: 'Tu sesión expiró. Por favor escribe *agendar* para comenzar de nuevo.' } }];
}

const dur = Number(selectedService.duracion_min || 30);
function toMinutes(hhmm){ const [h,m]=hhmm.split(':').map(Number); return h*60+m; }
function toHHMM(mins){ const h=Math.floor(mins/60); const m=mins%60; return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}`; }
const endHHMM = toHHMM(toMinutes(startHHMM) + dur);

const appointmentId = Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
const dateObj = new Date(selectedDay + 'T12:00:00');
const dayNames = ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];
const monthNames = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const displayDate = `${dayNames[dateObj.getDay()]} ${dateObj.getDate()} de ${monthNames[dateObj.getMonth()]}`;

// Limpiar servicio seleccionado después de agendar
delete staticData.selectedServiceByPhone[phoneNumber];

return [{ json: { 
  phoneNumber, 
  phoneNumberId, 
  contactName, 
  selectedDay, 
  hora: startHHMM, 
  hora_fin: endHHMM, 
  servicio: selectedService.nombre, 
  appointmentId, 
  estado: 'confirmado', 
  created_at: new Date().toISOString(), 
  displayDate, 
  duracion_min: dur 
} }];

