// Parse actions y detectar si debe responder con audio
const output = $json.output || '';
const base = $('Prepare Chat Input').first().json;
const isFromAudio = base.isFromAudio || false;

let action = 'send_text';
let clean = output;

// Detectar acciones especiales
if (output.includes('<<ACTION:SHOW_SERVICES>>')) {
  action = 'show_services';
  clean = output.replace(/<<ACTION:SHOW_SERVICES>>/g,'').trim();
} else if (output.includes('<<ACTION:CANCEL_APPOINTMENT>>')) {
  action = 'cancel_appointment';
  clean = output.replace(/<<ACTION:CANCEL_APPOINTMENT>>/g,'').trim();
} else if (isFromAudio) {
  // Si el mensaje original fue audio y no hay acción especial, responder con audio
  action = 'send_audio';
}

return { json: { action, output: clean, isFromAudio, ...base } };

// Preparar audio con mime type correcto para WhatsApp
const item = $input.first();
const originalBinary = item.binary.data;

return [{
  json: {
    phoneNumber: $('Parse Actions').first().json.phoneNumber,
    phoneNumberId: $('Parse Actions').first().json.phoneNumberId,
    output: $('Parse Actions').first().json.output
  },
  binary: {
    data: {
      ...originalBinary,
      mimeType: 'audio/mpeg',
      fileName: 'response.mp3',
      fileExtension: 'mp3'
    }
  }
}];
